  "sources": ["src/app/components/shop/collection/widgets/sidebar/sidebar.component.scss"],
  "sourcesContent": ["// ============================================================\n// Collection Sidebar — \"Editorial Filter Studio\" Premium redesign\n// Clean white card · gradient section headers · premium accordion\n// ============================================================\n\n$sd-ink:         #0F1720;\n$sd-ink-soft:    #2B3240;\n$sd-muted:       #6B7280;\n$sd-bg:          #FFFFFF;\n$sd-surface:     #F8F9FB;\n$sd-line:        #E6E8EC;\n$sd-blue:        #1E7FC9;\n$sd-blue-dark:   #135a95;\n$sd-blue-soft:   #EAF3FB;\n$sd-gold:        #B38A48;\n$sd-gold-soft:   #F6EFDE;\n$sd-rose:        #E7475A;\n\n:host { display: block; font-family: inherit; }\n\n// ---- Sidebar outer card ----\n.shop-left-sidebar {\n  background: $sd-bg;\n  border-radius: 20px;\n  border: 1px solid $sd-line;\n  overflow: hidden;\n  box-shadow:\n    0 2px 4px rgba($sd-ink, 0.03),\n    0 14px 36px rgba($sd-ink, 0.08);\n  position: sticky;\n  top: 90px;\n}\n\n// ---- Back button (mobile off-canvas) ----\n.back-button {\n  display: none;\n  padding: 16px 22px;\n  border-bottom: 1px solid $sd-line;\n\n  h3 { margin: 0; }\n\n  a {\n    display: inline-flex;\n    align-items: center;\n    gap: 10px;\n    font-size: 13px;\n    font-weight: 700;\n    color: $sd-ink;\n    text-decoration: none;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n\n    i { font-size: 18px !important; color: $sd-ink !important; }\n  }\n\n  @media (max-width: 991px) { display: block; }\n}\n\n// ---- Accordion overrides ----\n:host ::ng-deep {\n  .custome-accordion {\n    border: none !important;\n    border-radius: 0 !important;\n    background: transparent;\n  }\n\n  .accordion-item {\n    border: none !important;\n    border-bottom: 1px solid $sd-line !important;\n    border-radius: 0 !important;\n    background: transparent;\n\n    &:last-child { border-bottom: none !important; }\n  }\n\n  // Section header button\n  .accordion-header {\n    margin: 0 !important;\n  }\n\n  .accordion-button {\n    padding: 18px 22px !important;\n    background: transparent !important;\n    border: none !important;\n    outline: none !important;\n    box-shadow: none !important;\n    display: flex !important;\n    align-items: center !important;\n    justify-content: space-between !important;\n    width: 100% !important;\n    cursor: pointer;\n    transition: background 0.25s ease !important;\n    gap: 12px;\n    position: relative;\n\n    // Left accent bar when expanded\n    &::before {\n      content: '' !important;\n      position: absolute;\n      left: 0;\n      top: 14px;\n      bottom: 14px;\n      width: 3px !important;\n      background: $sd-blue !important;\n      border-radius: 0 3px 3px 0;\n      opacity: 0;\n      transform: scaleY(0.3);\n      transition: opacity 0.3s ease, transform 0.3s ease;\n      background-image: none !important;\n    }\n\n    // Expand chevron\n    &::after {\n      content: '\\ea4e' !important; // ri-arrow-down-s-line\n      font-family: 'remixicon' !important;\n      width: 30px !important;\n      height: 30px !important;\n      border-radius: 50% !important;\n      background: $sd-surface !important;\n      border: 1px solid $sd-line !important;\n      color: $sd-ink !important;\n      font-size: 16px !important;\n      display: flex !important;\n      align-items: center !important;\n      justify-content: center !important;\n      transition: all 0.35s cubic-bezier(0.22, 1, 0.36, 1) !important;\n      background-image: none !important;\n      transform: none !important;\n      flex-shrink: 0;\n    }\n\n    > span,\n    > .text-content {\n      font-size: 12px !important;\n      font-weight: 800 !important;\n      letter-spacing: 2.5px !important;\n      text-transform: uppercase !important;\n      color: $sd-ink !important;\n      flex: 1;\n    }\n\n    &:hover {\n      background: $sd-surface !important;\n\n      &::after {\n        border-color: $sd-blue !important;\n        color: $sd-blue !important;\n      }\n    }\n\n    &[aria-expanded=\"true\"],\n    &:not(.collapsed) {\n      &::before {\n        opacity: 1;\n        transform: scaleY(1);\n      }\n\n      &::after {\n        background: $sd-ink !important;\n        border-color: $sd-ink !important;\n        color: #fff !important;\n        transform: rotate(180deg) !important;\n        box-shadow: 0 4px 10px rgba($sd-ink, 0.2) !important;\n      }\n\n      > span,\n      > .text-content {\n        color: $sd-blue !important;\n      }\n    }\n  }\n\n  .accordion-collapse {\n    background: transparent;\n  }\n\n  .accordion-body {\n    padding: 6px 0 16px !important;\n    background: transparent;\n  }\n}\n"],
  "mappings": ";AAkBA;AAAQ,WAAA;AAAgB,eAAA;;AAGxB,CAAA;AACE,cAde;AAef,iBAAA;AACA,UAAA,IAAA,MAAA;AACA,YAAA;AACA,cACE,EAAA,IAAA,IAAA,KAAA,EAAA,EAAA,EAAA,EAAA,EAAA,EAAA,KAAA,EAAA,EAAA,KAAA,KAAA,KAAA,EAAA,EAAA,EAAA,EAAA,EAAA,EAAA;AAEF,YAAA;AACA,OAAA;;AAIF,CAAA;AACE,WAAA;AACA,WAAA,KAAA;AACA,iBAAA,IAAA,MAAA;;AAEA,CALF,YAKE;AAAK,UAAA;;AAEL,CAPF,YAOE;AACE,WAAA;AACA,eAAA;AACA,OAAA;AACA,aAAA;AACA,eAAA;AACA,SA1Ca;AA2Cb,mBAAA;AACA,kBAAA;AACA,kBAAA;;AAEA,CAlBJ,YAkBI,EAAA;AAAI,aAAA;AAA4B,SAAA;;AAGlC,OAAA,CAAA,SAAA,EAAA;AArBF,GAAA;AAqB8B,aAAA;;;AAK5B,MAAA,UAAA,CAAA;AACE,UAAA;AACA,iBAAA;AACA,cAAA;;AAGF,MAAA,UAAA,CAAA;AACE,UAAA;AACA,iBAAA,IAAA,MAAA;AACA,iBAAA;AACA,cAAA;;AAEA,MAAA,UAAA,CANF,cAME;AAAe,iBAAA;;AAIjB,MAAA,UAAA,CAAA;AACE,UAAA;;AAGF,MAAA,UAAA,CAAA;AACE,WAAA,KAAA;AACA,cAAA;AACA,UAAA;AACA,WAAA;AACA,cAAA;AACA,WAAA;AACA,eAAA;AACA,mBAAA;AACA,SAAA;AACA,UAAA;AACA,cAAA,WAAA,MAAA;AACA,OAAA;AACA,YAAA;;AAGA,MAAA,UAAA,CAhBF,gBAgBE;AACE,WAAA;AACA,YAAA;AACA,QAAA;AACA,OAAA;AACA,UAAA;AACA,SAAA;AACA,cAAA;AACA,iBAAA,EAAA,IAAA,IAAA;AACA,WAAA;AACA,aAAA,OAAA;AACA,cAAA,QAAA,KAAA,IAAA,EAAA,UAAA,KAAA;AACA,oBAAA;;AAIF,MAAA,UAAA,CAhCF,gBAgCE;AACE,WAAA;AACA,eAAA;AACA,SAAA;AACA,UAAA;AACA,iBAAA;AACA,cAAA;AACA,UAAA,IAAA,MAAA;AACA,SAAA;AACA,aAAA;AACA,WAAA;AACA,eAAA;AACA,mBAAA;AACA,cAAA,IAAA,MAAA,aAAA,IAAA,EAAA,CAAA,EAAA,IAAA,EAAA;AACA,oBAAA;AACA,aAAA;AACA,eAAA;;AAGF,MAAA,UAAA,CAnDF,iBAmDE,EAAA;AAAA,MAAA,UAAA,CAnDF,iBAmDE,EAAA,CAAA;AAEE,aAAA;AACA,eAAA;AACA,kBAAA;AACA,kBAAA;AACA,SAAA;AACA,QAAA;;AAGF,MAAA,UAAA,CA7DF,gBA6DE;AACE,cAAA;;AAEA,MAAA,UAAA,CAhEJ,gBAgEI,MAAA;AACE,gBAAA;AACA,SAAA;;AAMF,MAAA,UAAA,CAxEJ,gBAwEI,CAAA,mBAAA;AAAA,MAAA,UAAA,CAxEJ,gBAwEI,KAAA,CAAA,UAAA;AACE,WAAA;AACA,aAAA,OAAA;;AAGF,MAAA,UAAA,CA7EJ,gBA6EI,CAAA,mBAAA;AAAA,MAAA,UAAA,CA7EJ,gBA6EI,KAAA,CALA,UAKA;AACE,cAAA;AACA,gBAAA;AACA,SAAA;AACA,aAAA,OAAA;AACA,cAAA,EAAA,IAAA,KAAA,KAAA,EAAA,EAAA,EAAA,EAAA,EAAA,EAAA;;AAGF,MAAA,UAAA,CArFJ,gBAqFI,CAAA,oBAAA,EAAA;AAAA,MAAA,UAAA,CArFJ,gBAqFI,CAAA,oBAAA,EAAA,CAlCF;AAkCE,MAAA,UAAA,CArFJ,gBAqFI,KAAA,C